function validate([colors]) {
  if (typeof colors !== 'string' || colors.length < 1 || colors.length > 100000) return 'colors needs 1 to 100000 characters.';
  if (!/^[AB]+$/.test(colors)) return "colors may contain only 'A' and 'B'.";
  return null;
}

