    const left = colors[i - 1];
    const right = colors[i + 1];
    if (left !== colors[i] || right !== colors[i]) {
      continue;
    }
    if (colors[i] === 'A') {
      aliceMoves++;
    } else {
      bobMoves++;
    }
  }
  return aliceMoves > bobMoves;
