function generate(rand, size) {
  const limit = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const maxRun = size === 'large' ? 2 + Math.floor(rand() * 10) : 1 + Math.floor(rand() * 6);
  let colors = '';
  let color = rand() < 0.5 ? 'A' : 'B';
  while (colors.length < limit) {
    const run = 1 + Math.floor(rand() * maxRun);
    colors += color.repeat(Math.min(run, limit - colors.length));
    color = color === 'A' ? 'B' : 'A';
  }
  return [colors];
}
